def is_hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True

print(is_hashable("A"))
print(is_hashable(("A", 3)))
print(is_hashable(("A", [3])))
print(is_hashable([]))

def group_bookings(records):
    result = {}
    for room, day, name in records:
        key = (room, day)
        if key not in result:
            result[key] = []
        result[key].append(name)
    return result

print(group_bookings([]))
print(group_bookings([("A", "월", "민"), ("A", "월", "누")]))
print(group_bookings([("A", "월", "민"), ("A", "화", "민")]))

