def typed_counts(values):
    result = {}
    for value in values:
        key = (type(value).__name__, value)
        result[key] = result.get(key, 0) + 1
    return result

print(typed_counts([]))
print(typed_counts([1, True, 1.0, True]))
print(typed_counts([0, False, 0.0]))

def update_email(profiles, user_id, email):
    if user_id not in profiles:
        return False
    updated = profiles[user_id].copy()
    updated["email"] = email
    profiles[user_id] = updated
    return True

for profiles, user_id, email in [({}, "A", "x"), ({"A": {"email": "old"}, "B": {"email": "same"}}, "A", "same"), ({"A": {"email": "x"}}, "B", "y")]:
    print(update_email(profiles, user_id, email), profiles)
shared = {"email": "old"}
profiles = {"A": shared, "B": shared}
print(update_email(profiles, "A", "new"), profiles)
